AssistantMessageToolRequest(name='create', tool_call_id='tooluse_tLNH6m53z8syZPGyAIwZu4', arguments={'file_text': 'const form = document.getElementById('contactForm');
const fullNameInput = document.getElementById('fullName');
const emailInput = document.getElementById('email');
const phoneInput = document.getElementById('phone');
const submitButton = form.querySelector('button[type="submit"]');

const validationRules = {
    fullName: {
        required: true,
        validate: (value) => {
            if (!value.trim()) {
                return 'Full name is required';
            }
            if (value.trim().length < 2) {
                return 'Full name must be at least 2 characters';
            }
            return null;
        }
    },
    email: {
        required: true,
        validate: (value) => {
            if (!value.trim()) {
                return 'Email address is required';
            }
            const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
            if (!emailRegex.test(value.trim())) {
                return 'Please enter a valid email address';
            }
            return null;
        }
    },
    phone: {
        required: false,
        validate: (value) => {
            if (!value.trim()) {
                return null;
            }
            const phoneRegex = /^[\+]?[(]?[0-9]{3}[)]?[-\s\.]?[0-9]{3}[-\s\.]?[0-9]{4,6}$/;
            if (!phoneRegex.test(value.trim())) {
                return 'Please enter a valid phone number (e.g., +1 (555) 123-4567)';
            }
            return null;
        }
    }
};

function showValidationMessage(input, message) {
    const field = input.closest('.form-field');
    const messageElement = field.querySelector('.validation-message');

    if (message) {
        input.classList.add('error');
        input.classList.remove('success');
        messageElement.textContent = message;
    } else {
        input.classList.remove('error');
        if (input.value.trim()) {
            input.classList.add('success');
        } else {
            input.classList.remove('success');
        }
        messageElement.textContent = '';
    }
}

function validateField(input) {
    const fieldName = input.name;
    const rules = validationRules[fieldName];

    if (!rules) return true;

    const error = rules.validate(input.value);
    showValidationMessage(input, error);

    return !error;
}

function validateForm() {
    let isValid = true;

    Object.keys(validationRules).forEach((fieldName) => {
        const input = document.getElementById(fieldName);
        if (!validateField(input)) {
            isValid = false;
        }
    });

    return isValid;
}

fullNameInput.addEventListener('blur', () => validateField(fullNameInput));
fullNameInput.addEventListener('input', () => {
    if (fullNameInput.classList.contains('error')) {
        validateField(fullNameInput);
    }
});

emailInput.addEventListener('blur', () => validateField(emailInput));
emailInput.addEventListener('input', () => {
    if (emailInput.classList.contains('error')) {
        validateField(emailInput);
    }
});

phoneInput.addEventListener('blur', () => validateField(phoneInput));
phoneInput.addEventListener('input', () => {
    if (phoneInput.classList.contains('error')) {
        validateField(phoneInput);
    }
});

form.addEventListener('submit', (e) => {
    e.preventDefault();

    if (!validateForm()) {
        return;
    }

    submitButton.disabled = true;
    submitButton.textContent = 'Sending...';

    setTimeout(() => {
        const formData = {
            fullName: fullNameInput.value.trim(),
            email: emailInput.value.trim(),
            phone: phoneInput.value.trim()
        };

        console.log('Form submitted:', formData);

        const successMessage = document.createElement('div');
        successMessage.className = 'success-message';
        successMessage.textContent = '✓ Message sent successfully! We'll be in touch soon.';

        form.insertAdjacentElement('beforebegin', successMessage);

        form.reset();
        fullNameInput.classList.remove('success');
        emailInput.classList.remove('success');
        phoneInput.classList.remove('success');

        submitButton.disabled = false;
        submitButton.textContent = 'Send Message';

        setTimeout(() => {
            successMessage.remove();
        }, 5000);
    }, 800);
});
